import AppKit

/// The About panel's credits for one app bundle: one link to its bundled
/// third-party notices (`THIRD_PARTY_LICENSES.md`, generated by
/// scripts/cmux-next/generate-third-party-notices.sh), so the licenses that
/// cmux ships under (MIT credits such as t3code included) are one click from
/// About cmux. A DEV build made with the explicit `CMUX_NEXT_SKIP_RB_HOST=1`
/// opt-out also says so here: embed-remote-browser-host.sh writes
/// `RemoteBrowserHostOptOut.txt` into the bundle's resources.
struct AboutPanelCredits {
    let bundle: Bundle

    /// The link text.
    static var title: String {
        String(localized: "about.credits.licenses", defaultValue: "Third-Party Licenses", table: "Windows", bundle: .module)
    }

    /// The line shown when the build opted out of the remote browser host.
    static var remoteBrowserHostOptOut: String {
        String(
            localized: "about.credits.remoteBrowserHostOptOut",
            defaultValue: "Built without the remote browser host (CMUX_NEXT_SKIP_RB_HOST=1)",
            table: "Windows",
            bundle: .module
        )
    }

    /// The notices file inside the bundle, when it has one.
    var licensesURL: URL? {
        bundle.url(forResource: "THIRD_PARTY_LICENSES", withExtension: "md")
    }

    /// Whether the build opted out of embedding the remote browser host.
    var remoteBrowserHostOptedOut: Bool {
        bundle.url(forResource: "RemoteBrowserHostOptOut", withExtension: "txt") != nil
    }

    /// Credits text: a link to the notices file and the opt-out line, each
    /// when present; nil when neither is.
    var credits: NSAttributedString? {
        let centered = NSMutableParagraphStyle()
        centered.alignment = .center
        let font = NSFont.systemFont(ofSize: NSFont.smallSystemFontSize)
        var lines: [NSAttributedString] = []
        if let url = licensesURL {
            lines.append(NSAttributedString(string: Self.title, attributes: [.link: url, .font: font, .paragraphStyle: centered]))
        }
        if remoteBrowserHostOptedOut {
            lines.append(NSAttributedString(string: Self.remoteBrowserHostOptOut, attributes: [
                .font: font,
                .foregroundColor: NSColor.systemOrange,
                .paragraphStyle: centered,
            ]))
        }
        guard !lines.isEmpty else { return nil }
        let out = NSMutableAttributedString()
        for (index, line) in lines.enumerated() {
            if index > 0 { out.append(NSAttributedString(string: "\n", attributes: [.font: font, .paragraphStyle: centered])) }
            out.append(line)
        }
        return out
    }
}
